import pathlib,json,base64,hashlib,hmac,re,subprocess,tempfile,os
def fingerprint(key):
    fields=key.split()
    if len(fields)<2 or fields[0]!='ssh-ed25519':raise ValueError('only Ed25519 public keys supported')
    try:
        with tempfile.TemporaryDirectory(prefix='.keycheck-',dir='.') as d:
            p=pathlib.Path(d)/'key.pub';p.write_text(' '.join(fields[:2])+'\n')
            r=subprocess.run(['ssh-keygen','-l','-E','sha256','-f',str(p)],capture_output=True,text=True,timeout=3)
            if r.returncode:raise ValueError('malformed public key')
            return r.stdout.split()[1]
    except (IndexError,subprocess.SubprocessError) as e:raise ValueError('key validation failed') from e
def aliases(token):
    if token.startswith('|1|'):
        parts=token.split('|')
        try:
            if len(parts)!=4 or len(base64.b64decode(parts[2],validate=True))!=20 or len(base64.b64decode(parts[3],validate=True))!=20:raise ValueError('invalid hash')
        except Exception as e:raise ValueError('invalid hashed host') from e
        return [token]
    values=token.split(',')
    if any(not re.fullmatch(r'(?:[A-Za-z0-9.-]+|\[[A-Za-z0-9.-]+\]:[1-9][0-9]{0,4})',v) for v in values):raise ValueError('only concrete host names supported')
    for value in values:
        if value.startswith('[') and int(value.rsplit(':',1)[1])>65535:raise ValueError('invalid host port')
    return values
def matches(token,host):
    if not token.startswith('|1|'):return token==host
    _,_,salt,digest=token.split('|')
    return hmac.compare_digest(hmac.new(base64.b64decode(salt),host.encode(),hashlib.sha1).digest(),base64.b64decode(digest))
def execute(source,manifest,new_key,output):
    source,manifest,new_key,output=map(pathlib.Path,(source,manifest,new_key,output))
    if output.resolve() in {p.resolve() for p in (source,manifest,new_key)}:raise ValueError('output must differ from all inputs')
    approved=json.loads(manifest.read_text())
    if not isinstance(approved,dict) or not all(isinstance(approved.get(k),str) for k in ['host','ticket','old_fingerprint','new_fingerprint']):raise ValueError('invalid approval fields')
    if any(ord(ch)<32 or ord(ch)==127 for ch in approved['ticket']):raise ValueError('control character in ticket')
    host=approved['host']
    if aliases(host)!=[host] or host.startswith('|') or not isinstance(approved.get('ticket'),str) or not approved['ticket'].strip():raise ValueError('explicit target and approval required')
    key_lines=[line for line in new_key.read_text().splitlines() if line.strip()]
    if len(key_lines)!=1:raise ValueError('exactly one new public key required')
    new=' '.join(key_lines[0].split()[:2]);new_fp=fingerprint(new)
    if new_fp!=approved['new_fingerprint'] or new_fp==approved['old_fingerprint']:raise ValueError('new key approval mismatch')
    result=[];count=0
    for line in source.read_text().splitlines(keepends=True):
        if not line.strip() or line.lstrip().startswith('#'):result.append(line);continue
        fields=line.strip().split(None,3)
        if len(fields)<3:raise ValueError('malformed known_hosts')
        names=aliases(fields[0]);key=' '.join(fields[1:3]);fp=fingerprint(key)
        hits=[name for name in names if matches(name,host)]
        if hits:
            if len(hits)!=1 or fp!=approved['old_fingerprint']:raise ValueError('ambiguous or unexpected current host key')
            count+=1
            remaining=[name for name in names if name not in hits]
            if remaining:result.append(','.join(remaining)+' '+key+(' '+fields[3] if len(fields)>3 else '')+'\n')
            result.append(hits[0]+' '+new+' # approved '+approved['ticket'].strip().replace('\n',' ')+'\n')
        else:result.append(line)
    if count!=1:raise ValueError('exactly one matching approved old key required')
    fd,name=tempfile.mkstemp(prefix='.known-hosts-',dir=output.parent)
    try:
        with os.fdopen(fd,'w') as stream:stream.write(''.join(result));stream.flush();os.fsync(stream.fileno())
        os.chmod(name,0o600);os.replace(name,output)
    finally:
        if os.path.exists(name):os.unlink(name)
